<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { useRoute, useRouter } from 'vue-router'
import { Settings2, Save, Search } from 'lucide-vue-next'
import { api, queries, write } from '../api/client'
import type { components } from '../api/schema'
import { t, date } from '../app/i18n'
import { useDeployment, rollout, nodeTone } from '../app/cluster'
import NodePicker from '../components/NodePicker.vue'
import { notify, errorText } from '../app/feedback'
import { secure } from '../app/security'
import ErrorNotice from '../components/ErrorNotice.vue'
import UiSelect from '../components/ui/UiSelect.vue'
import UiSwitch from '../components/ui/UiSwitch.vue'
import UiDialog from '../components/ui/UiDialog.vue'

type RuntimeSettings = components['schemas']['RuntimeSettingsView']
type ConfigField = components['schemas']['ConfigField']
type RuntimeField = { key: string; valueType: 'text' | 'number' | 'storage'; example?: string; optional?: boolean; options?: string[] }

const runtimeSettings = useQuery({ queryKey: ['runtime-settings'], queryFn: ({ signal }) => api<RuntimeSettings[]>('/api/v1/runtime-settings', { signal }) })
const router = useRouter(), route = useRoute()
const { status, cluster, overview } = useDeployment()
const nodeView = computed(() => cluster.value && route.query.view === 'node')
const selected = computed({ get: () => typeof route.query.node === 'string' ? route.query.node : '', set: node => { void router.replace({ query: { ...route.query, node: node || undefined } }) } })
const nodeConfig = useQuery({ queryKey: ['cluster-node-config', selected], enabled: computed(() => nodeView.value && !!selected.value), queryFn: ({ signal }) => api<components['schemas']['NodeConfig']>(`/api/v1/cluster/nodes/${encodeURIComponent(selected.value)}/config`, { signal }), refetchInterval: () => nodeView.value && selected.value ? 15_000 : false })
const controlSettings = computed(() => runtimeSettings.data.value?.find(row => row.section === 'web'))
const controlRollout = computed(() => rollout(overview.data.value, 'web'))
const storages = useQuery({ queryKey: ['storages'], queryFn: ({ signal }) => api<components['schemas']['StorageView'][]>('/api/v1/storages', { signal }) })
const stagingOptions = computed(() => [{ value: '', label: t('notConfigured') }, ...(storages.data.value || []).filter(row => row.type === 's3' && row.enabled).map(row => ({ value: row.id, label: row.name }))])
const config = useQuery({ queryKey: ['service-config'], queryFn: ({ signal }) => api<ConfigField[]>('/api/v1/system/config', { signal }) })
const controlDraft = ref({ origin: '', secure_cookie: true, session_lifetime: '', gravatar_base_url: '' })
const settingsBusy = ref(false), section = ref(typeof route.query.section === 'string' ? route.query.section : ''), search = ref(''), settingsError = ref('')
const runtimeOpen = ref(false), runtimeSection = ref(''), runtimeRevision = ref(0), runtimeDraft = ref<Record<string, unknown>>({}), runtimeError = ref('')
const runtimeDefinitions: Record<string, { title: string; fields: RuntimeField[] }> = {
  io: { title: 'runtimeGroupIo', fields: [{ key: 'sqlite_synchronous', valueType: 'text', options: ['full', 'normal', 'off'] }] },
  requests: { title: 'runtimeGroupRequests', fields: [{ key: 's3_domain', valueType: 'text', optional: true }, { key: 's3_region', valueType: 'text' }, { key: 's3_chunk_limit', valueType: 'text', example: '8MiB' }, { key: 'read_idle_timeout', valueType: 'text', example: '120s' }, { key: 'upload_idle_timeout', valueType: 'text', example: '120s' }] },
  uploads: { title: 'runtimeGroupUploads', fields: [{ key: 'sweep_interval', valueType: 'text', example: '5m' }, { key: 'client_idle_timeout', valueType: 'text', example: '120s' }, { key: 'max_active_uploads', valueType: 'number', optional: true }, { key: 'staging_storage_id', valueType: 'storage', optional: true }, { key: 'staging_bytes_limit', valueType: 'text', example: '10GiB', optional: true }] },
  metrics: { title: 'runtimeGroupMetrics', fields: [{ key: 'scope_limit', valueType: 'number' }, { key: 'storage_interval', valueType: 'text' }, { key: 'storage_retention', valueType: 'text' }, { key: 'runtime_interval', valueType: 'text' }, { key: 'runtime_retention', valueType: 'text' }, { key: 'refresh_interval', valueType: 'text' }, { key: 'query_timeout', valueType: 'text' }, { key: 'access_flush_interval', valueType: 'text' }, { key: 'access_retention', valueType: 'text' }] },
  maintenance: { title: 'runtimeGroupMaintenance', fields: [{ key: 'interval', valueType: 'text' }, { key: 'batch_size', valueType: 'number' }, { key: 'max_duration', valueType: 'text' }, { key: 'task_retention', valueType: 'text' }, { key: 'audit_retention', valueType: 'text' }] },
}
const runtimeFieldGroups = computed(() => { const definition = runtimeDefinitions[runtimeSection.value]; return definition ? [{ title: definition.title, fields: definition.fields.filter(field => field.key in runtimeDraft.value) }] : [] })
const editableSections = computed(() => (runtimeSettings.data.value || []).filter(row => row.section in runtimeDefinitions).map(row => ({ ...row, rollout: rollout(overview.data.value, row.section) })))
const sourceFields = computed(() => nodeView.value ? nodeConfig.data.value?.fields || [] : (config.data.value || []).filter(row => !cluster.value || row.origin === 'database'))
const sections = computed(() => [{ value: '', label: t('allConfigSections') }, ...[...new Set((sourceFields.value).map(row => row.key.split('.')[0]!))].map(value => ({ value, label: t('configSection_' + value) }))])
const fields = computed(() => sourceFields.value.filter(row => (!section.value || row.key.startsWith(section.value + '.')) && `${row.key} ${fieldLabel(row.key)} ${row.value}`.toLowerCase().includes(search.value.toLowerCase())))
const visibleFields = computed(() => fields.value.filter(row => !row.key.startsWith('effective.')))
const advancedFields = computed(() => fields.value.filter(row => row.key.startsWith('effective.')))
function human(key: string) { return key.split('.').map(part => part.replaceAll('_', ' ').replace(/\b\w/g, char => char.toUpperCase())).join(' · ') }
function configKey(prefix: string, key: string) { return prefix + key.replace('.', '_') }
function fieldLabel(key: string) { if (key.startsWith('replica_database.') && !key.endsWith('.observed_at')) key = key.replace('replica_database.', 'database.'); const [group, name] = key.split('.'); const value = group && (group in runtimeDefinitions || group === 'web') ? t('runtimeField_' + name) : t(configKey('configField_', key)); return value.startsWith('runtimeField_') || value.startsWith('configField_') ? human(key) : value }
function fieldHelp(key: string) { if (key.startsWith('replica_database.') && !key.endsWith('.observed_at')) key = key.replace('replica_database.', 'database.'); const [group, name] = key.split('.'); const value = group && (group in runtimeDefinitions || group === 'web') ? t('runtimeHelp_' + name) : t(configKey('configHelp_', key)); return value.startsWith('runtimeHelp_') || value.startsWith('configHelp_') ? t('runtimeFieldHint') : value }
watch(section, section => { if (cluster.value) void router.replace({ query: { ...route.query, section: section || undefined } }) })
watch(controlSettings, row => { if (row && !settingsBusy.value && row.value && typeof row.value === 'object') controlDraft.value = { ...controlDraft.value, ...(row.value as Partial<typeof controlDraft.value>) } }, { immediate: true })

async function saveControlSettings() {
  settingsBusy.value = true; settingsError.value = ''
  try { const result = await secure(() => write<RuntimeSettings>('/api/v1/runtime-settings/web', { value: controlDraft.value, revision: controlSettings.value?.revision }, 'PUT')); await Promise.all(['service-status', 'cluster-status', 'cluster-nodes', 'cluster-node-config'].map(key => queries.invalidateQueries({ queryKey: [key] }))); await runtimeSettings.refetch(); await config.refetch(); notify(t(cluster.value ? 'clusterSettingsSaved' : result.restart_required ? 'settingsSavedRestart' : 'controlSettingsSaved'), cluster.value ? t('clusterSettingsSavedHint') : result.restart_required ? t('restartPendingHint') : undefined, cluster.value || result.restart_required ? 'info' : 'success') }
  catch (error) { settingsError.value = errorText(error) } finally { settingsBusy.value = false }
}
function runtimeFieldTarget(key: string) {
  const [section, field] = key.split('.')
  if (!section || !field || section === 'effective' || section === 'pack') return null
  if (section === 'web') return { section, field }
  const definition = runtimeDefinitions[section]
  return definition?.fields.some(item => item.key === field) ? { section, field } : null
}
function focusConfigField(key: string) {
  const field = document.querySelector<HTMLElement>(`[data-runtime-field="${key}"]`)
  const control = field?.matches('input,button') ? field : field?.querySelector<HTMLElement>('input,button')
  control?.scrollIntoView({ behavior: 'smooth', block: 'center' }); control?.focus()
}
function editRuntime(row: RuntimeSettings, focusKey = '') { runtimeSection.value = row.section; runtimeRevision.value = row.revision; runtimeDraft.value = row.value && typeof row.value === 'object' ? { ...(row.value as Record<string, unknown>) } : {}; runtimeError.value = ''; runtimeOpen.value = true; if (focusKey) void nextTick(() => focusConfigField(`${row.section}.${focusKey}`)) }
function canEditConfig(row: ConfigField) { return !nodeView.value && row.origin === 'database' && (row.key === 'pack.creation_enabled' || !!runtimeFieldTarget(row.key)) }
function editConfigField(row: ConfigField) {
  if (row.key === 'pack.creation_enabled') { void router.push({ path: '/maintenance', query: { focus: 'pack-creation' } }); return }
  const target = runtimeFieldTarget(row.key)
  if (!target) return
  if (target.section === 'web') { focusConfigField(row.key); return }
  const settings = runtimeSettings.data.value?.find(item => item.section === target.section)
  if (settings) editRuntime(settings, target.field)
}
function updateRuntimeField(field: RuntimeField, value: string | number | null) { runtimeDraft.value[field.key] = field.optional && value === '' ? null : value }
function inputRuntimeField(field: RuntimeField, event: Event) { const value = (event.target as HTMLInputElement).value; updateRuntimeField(field, field.valueType === 'number' ? (value === '' ? null : Number(value)) : value) }
async function saveRuntime() {
  runtimeError.value = ''; settingsBusy.value = true
  try { const result = await secure(() => write<RuntimeSettings>(`/api/v1/runtime-settings/${encodeURIComponent(runtimeSection.value)}`, { value: runtimeDraft.value, revision: runtimeRevision.value }, 'PUT')); await Promise.all(['service-status', 'cluster-status', 'cluster-nodes', 'cluster-node-config'].map(key => queries.invalidateQueries({ queryKey: [key] }))); runtimeOpen.value = false; await runtimeSettings.refetch(); await config.refetch(); notify(t(cluster.value ? 'clusterSettingsSaved' : result.restart_required ? 'settingsSavedRestart' : 'runtimeSettingsSaved'), cluster.value ? t('clusterSettingsSavedHint') : result.restart_required ? t('restartPendingHint') : undefined, cluster.value || result.restart_required ? 'info' : 'success') }
  catch (error) { runtimeError.value = errorText(error) } finally { settingsBusy.value = false }
}
</script>

<template>
  <div class="page-heading"><div><p class="eyebrow">{{ t('runtimeConfigEyebrow') }}</p><h1>{{ t('runtimeConfig') }}</h1><p>{{ t(cluster ? 'clusterConfigHint' : 'runtimeConfigHint') }}</p></div></div>
  <nav v-if="cluster" class="tabs-list cluster-scopes" :aria-label="t('clusterConfigScope')"><RouterLink class="tab-trigger" :class="{ active: !nodeView }" :aria-current="!nodeView ? 'page' : undefined" :to="{ query: { ...route.query, view: undefined } }" active-class="" exact-active-class="">{{ t('clusterDeploymentSettings') }}</RouterLink><RouterLink class="tab-trigger" :class="{ active: nodeView }" :aria-current="nodeView ? 'page' : undefined" :to="{ query: { ...route.query, view: 'node' } }" active-class="" exact-active-class="">{{ t('clusterNodeInformation') }}</RouterLink></nav>
  <section v-if="nodeView" class="surface config-board runtime-config-card node-config-context"><div class="section-heading"><div><h2>{{ t('clusterNodeInformation') }}</h2><p class="field-help">{{ t('clusterConnectedControl', { name: status.data.value?.current_node?.name || '—' }) }}</p></div><NodePicker v-model="selected" :name="nodeConfig.data.value?.node.name" /></div><template v-if="nodeConfig.data.value"><div class="node-detail-status"><strong>{{ nodeConfig.data.value.node.name }}</strong><span class="badge">{{ t('nodeRole_' + nodeConfig.data.value.node.role) }}</span><span class="badge node-state" :data-tone="nodeTone(nodeConfig.data.value.node.configuration)">{{ t('nodeState_' + nodeConfig.data.value.node.configuration) }}</span></div><p class="technical-key field-help">{{ nodeConfig.data.value.node.id }}</p><p class="field-help">{{ t('clusterLoadedAt', { time: nodeConfig.data.value.loaded_at ? date(nodeConfig.data.value.loaded_at) : '—' }) }}</p><p class="field-help">{{ t('clusterSnapshotAt', { time: nodeConfig.data.value.node.sampled_at ? date(nodeConfig.data.value.node.sampled_at) : '—' }) }}</p><p v-if="!nodeConfig.data.value.node.report_fresh" class="info-callout">{{ t('clusterReportStaleHint') }}</p></template><p v-else-if="!selected" class="field-help">{{ t('clusterChooseNodeHint') }}</p><p class="field-help">{{ t('clusterLoadedConfigHint') }}</p><dl v-if="nodeConfig.data.value" class="facts node-config-revisions"><template v-for="(revision, group) in (nodeConfig.data.value.revisions as Record<string, number>)" :key="group"><dt>{{ t('configSection_' + group) }}</dt><dd><span>{{ t('revisionLabel', { value: revision }) }}</span><span class="badge node-state" :data-tone="nodeTone((nodeConfig.data.value.node.settings as Record<string, string>)[group] || 'unknown')">{{ t('nodeState_' + ((nodeConfig.data.value.node.settings as Record<string, string>)[group] || 'unknown')) }}</span></dd></template></dl><RouterLink class="text-button" :to="{ query: { ...route.query, view: undefined } }">{{ t('clusterDeploymentSettings') }}</RouterLink><ErrorNotice v-if="nodeConfig.error.value" :error="nodeConfig.error.value" /></section>
  <ErrorNotice v-if="config.error.value || runtimeSettings.error.value || storages.error.value" :error="config.error.value || runtimeSettings.error.value || storages.error.value" />
  <section v-if="!nodeView" class="surface config-board runtime-config-card">
    <div class="section-heading"><div><h2><Settings2 :size="19" />{{ t('controlSettings') }}</h2><p class="field-help">{{ t('controlSettingsHint') }}</p></div><RouterLink v-if="cluster" class="badge node-state" :data-tone="nodeTone(controlRollout.state)" to="/service?section=web">{{ controlRollout.text }}</RouterLink><span v-else-if="controlSettings?.restart_required" class="badge node-state" :data-tone="nodeTone('restart_required')">{{ t('restartRequired') }}</span></div>
    <form v-if="controlSettings" class="runtime-form" @submit.prevent="saveControlSettings">
      <label class="field" data-runtime-field="web.origin"><span>{{ t('controlOrigin') }}</span><input v-model="controlDraft.origin" required type="url" placeholder="https://mokyu.example.com" autocomplete="off" :disabled="settingsBusy"><small class="field-help">{{ t('runtimeHelp_origin') }}</small></label>
      <label class="field" data-runtime-field="web.session_lifetime"><span>{{ t('sessionLifetime') }}</span><input v-model="controlDraft.session_lifetime" required placeholder="12h" autocomplete="off" :disabled="settingsBusy"><small class="field-help">{{ t('runtimeHelp_session_lifetime') }}</small></label>
      <label class="field runtime-form-wide" data-runtime-field="web.gravatar_base_url"><span>{{ t('gravatarBaseUrl') }}</span><input v-model="controlDraft.gravatar_base_url" required type="url" autocomplete="off" :disabled="settingsBusy"><small class="field-help">{{ t('runtimeHelp_gravatar_base_url') }}</small></label>
      <UiSwitch v-model="controlDraft.secure_cookie" data-runtime-field="web.secure_cookie" :label="t('secureCookie')" :disabled="settingsBusy" />
      <p class="field-help runtime-form-wide">{{ t(cluster ? 'clusterSettingsSavedHint' : 'restartControlHint') }}</p>
      <p v-if="settingsError" class="error runtime-form-wide" role="alert">{{ settingsError }}</p>
      <div class="form-footer runtime-form-wide"><span class="field-help">{{ t('runtimeSaveHint') }}</span><button class="primary" :disabled="settingsBusy || !controlDraft.origin || !controlDraft.session_lifetime || !controlDraft.gravatar_base_url"><Save :size="16" />{{ t('saveControlSettings') }}</button></div>
    </form>
  </section>
  <section v-if="!nodeView" class="surface config-board runtime-config-card"><div class="section-heading"><div><h2>{{ t('runtimeSections') }}</h2><p class="field-help">{{ t('runtimeSectionsHint') }}</p></div></div><div class="runtime-section-list"><article v-for="row in editableSections" :key="row.section"><div><strong>{{ t(runtimeDefinitions[row.section]!.title) }}</strong><RouterLink v-if="cluster" class="badge node-state" :data-tone="nodeTone(row.rollout.state)" :to="{ path: '/service', query: { section: row.section } }">{{ row.rollout.text }}</RouterLink><span v-else class="badge node-state" :data-tone="nodeTone(row.restart_required ? 'restart_required' : 'applied')">{{ row.restart_required ? t('restartRequired') : t('appliedSetting') }}</span></div><span class="field-help">{{ t('revisionLabel', { value: row.revision }) }}</span><button @click="editRuntime(row)">{{ t('editRuntimeSettings') }}</button></article></div></section>
  <section class="surface config-board runtime-config-card"><div class="task-filters config-filterbar"><UiSelect v-model="section" :options="sections" :label="t('configSection')" /><label class="inline-search"><Search :size="17" /><input v-model="search" :placeholder="t('searchConfiguration')" :aria-label="t('searchConfiguration')"></label></div><div class="config-fields"><article v-for="row in visibleFields" :key="row.key"><div class="config-copy"><strong>{{ fieldLabel(row.key) }}</strong><code class="technical-key">{{ row.key }}</code><small class="field-help">{{ fieldHelp(row.key) }}</small></div><div class="config-value"><div class="config-value-line"><span class="badge config-origin-badge" :data-origin="row.origin">{{ t('configOrigin_' + row.origin) }}</span><span class="badge config-value-mode-badge" :data-mode="row.value_mode">{{ t('configValueMode_' + row.value_mode) }}</span><strong class="config-value-chip" :class="{ 'is-placeholder': row.value === '[redacted]' || row.value === 'null' }">{{ row.value_state ? t('configValueState_' + row.value_state) : row.value === '[redacted]' ? t('redactedValue') : row.value === 'null' ? t('notConfigured') : row.value }}</strong></div><div class="config-meta"><small>{{ nodeView ? t('configReadonly') : cluster && row.origin === 'database' ? t('clusterSavedTarget') : t(row.origin === 'environment' ? 'configReadonly' : row.restart ? 'restartRequired' : 'appliedSetting') }}</small><span v-if="canEditConfig(row)" class="config-meta-separator" aria-hidden="true">·</span><button v-if="canEditConfig(row)" type="button" class="config-edit-button" @click="editConfigField(row)">{{ t('editConfigField') }}</button></div></div></article></div><p v-if="config.data.value && !fields.length" class="field-help">{{ t('noConfigMatches') }}</p><details v-if="advancedFields.length" class="advanced-config"><summary>{{ t('advancedConfig') }} <span class="badge">{{ advancedFields.length }}</span></summary><p class="field-help">{{ t('advancedConfigHint') }}</p><div class="config-fields"><article v-for="row in advancedFields" :key="row.key"><div class="config-copy"><strong>{{ fieldLabel(row.key) }}</strong><code class="technical-key">{{ row.key }}</code><small class="field-help">{{ fieldHelp(row.key) }}</small></div><div class="config-value"><div class="config-value-line"><span class="badge config-origin-badge" :data-origin="row.origin">{{ t('configOrigin_' + row.origin) }}</span><span class="badge config-value-mode-badge" :data-mode="row.value_mode">{{ t('configValueMode_' + row.value_mode) }}</span><strong class="config-value-chip" :class="{ 'is-placeholder': row.value === '[redacted]' || row.value === 'null' }">{{ row.value_state ? t('configValueState_' + row.value_state) : row.value === '[redacted]' ? t('redactedValue') : row.value === 'null' ? t('notConfigured') : row.value }}</strong></div><div class="config-meta"><small>{{ nodeView ? t('configReadonly') : cluster && row.origin === 'database' ? t('clusterSavedTarget') : t(row.origin === 'environment' ? 'configReadonly' : row.restart ? 'restartRequired' : 'appliedSetting') }}</small><span v-if="canEditConfig(row)" class="config-meta-separator" aria-hidden="true">·</span><button v-if="canEditConfig(row)" type="button" class="config-edit-button" @click="editConfigField(row)">{{ t('editConfigField') }}</button></div></div></article></div></details></section>
  <UiDialog v-model:open="runtimeOpen" :title="t(runtimeDefinitions[runtimeSection]?.title || runtimeSection)" :description="t('runtimeEditorHint')" :busy="settingsBusy"><p v-if="runtimeError" class="error">{{ runtimeError }}</p><div class="runtime-editor-fields"><template v-for="group in runtimeFieldGroups" :key="group.title"><h3 class="runtime-group-title">{{ t(group.title) }}</h3><label v-for="field in group.fields" :key="field.key" class="field" :data-runtime-field="`${runtimeSection}.${field.key}`"><span>{{ fieldLabel(runtimeSection + '.' + field.key) }}</span><UiSelect v-if="field.options" :model-value="String(runtimeDraft[field.key])" :options="field.options.map(value => ({ value, label: t('sqliteSync_' + value) }))" :label="fieldLabel(runtimeSection + '.' + field.key)" :disabled="settingsBusy" @update:model-value="updateRuntimeField(field, $event)" /><UiSelect v-else-if="field.valueType === 'storage'" :model-value="String(runtimeDraft[field.key] || '')" :options="stagingOptions" :label="fieldLabel(runtimeSection + '.' + field.key)" :disabled="settingsBusy" @update:model-value="updateRuntimeField(field, $event)" /><input v-else :type="field.valueType === 'number' ? 'number' : 'text'" :placeholder="field.example" :value="runtimeDraft[field.key] == null ? '' : String(runtimeDraft[field.key])" :disabled="settingsBusy" @input="inputRuntimeField(field, $event)"><small class="field-help">{{ fieldHelp(runtimeSection + '.' + field.key) }}</small></label></template><p v-if="!runtimeFieldGroups.length" class="field-help">{{ t('notConfigured') }}</p></div><template #footer><button :disabled="settingsBusy" @click="runtimeOpen = false">{{ t('cancel') }}</button><button class="primary" :disabled="settingsBusy" @click="saveRuntime">{{ t('save') }}</button></template></UiDialog>
</template>
